-- =============================================================================
-- Conciliación Automatizada 2.0 · Hotel Plaza San Francisco
-- Script del sistema: creación de las tablas y poblamiento con datos ficticios
-- Motor: SQLite 3 (base del piloto). Versión de la aplicación: 3.14.0
-- =============================================================================
-- Uso:   sqlite3 conciliacion.sqlite3 < Script_Base_Datos.sql
--        Luego apuntar la aplicación a esa base con DATABASE_URL.
-- La estructura es la misma que crea «python manage.py migrate» (Django 5.2).
-- Todos los datos son ficticios: no hay información real del hotel.
-- Usuarios de prueba (contraseña Prueba-2026-x, guardada cifrada con PBKDF2):
--   admin@hoteldemo.cl         Administrador
--   tesoreria@hoteldemo.cl     Analista de Tesorería
--   contabilidad@hoteldemo.cl  Contador / Auditor
--   Cambia las contraseñas antes de usar la base con datos reales.
-- La tabla conciliacion_bintarjeta trae aquí solo los BIN de los datos de ejemplo;
-- para cargar la base completa (unos 375.000 BIN desde datos/bines.csv.gz), ejecutar:
--   python manage.py shell -c "import importlib; from django.apps import apps; importlib.import_module('apps.conciliacion.migrations.0003_cargar_bines').cargar(apps, None)"
-- (con «python manage.py migrate» sobre una base vacía no hace falta: la carga es automática).
-- =============================================================================

PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

-- -----------------------------------------------------------------------------
-- 1. CREACIÓN DE TABLAS
-- -----------------------------------------------------------------------------

-- Tablas del framework Django (registro de migraciones, tipos de contenido y permisos)
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);

-- Usuarios y perfiles
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);

-- Sesiones y bitácora del administrador de Django
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);

-- Tablas de la aplicación
CREATE TABLE IF NOT EXISTS "conciliacion_bintarjeta" ("bin" varchar(6) NOT NULL PRIMARY KEY, "marca" varchar(30) NOT NULL, "tipo" varchar(10) NOT NULL, "nivel" varchar(40) NOT NULL, "banco" varchar(120) NOT NULL, "pais_codigo" varchar(2) NOT NULL, "pais" varchar(60) NOT NULL);
CREATE TABLE IF NOT EXISTS "conciliacion_configuracion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tolerancia_clp" integer unsigned NOT NULL CHECK ("tolerancia_clp" >= 0), "tolerancia_usd" decimal NOT NULL, "ventana_dias" smallint unsigned NOT NULL CHECK ("ventana_dias" >= 0), "palabras_cartola" varchar(300) NOT NULL, "actualizada" datetime NOT NULL, "actualizada_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "conciliacion_conciliacion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "moneda" varchar(3) NOT NULL, "creada" datetime NOT NULL, "archivos" text NOT NULL CHECK ((JSON_VALID("archivos") OR "archivos" IS NULL)), "cuadrado" bool NOT NULL, "monto_por_revisar" decimal NOT NULL, "resultado" text NOT NULL CHECK ((JSON_VALID("resultado") OR "resultado" IS NULL)), "usuario_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "desde" date NULL, "hasta" date NULL);
CREATE TABLE IF NOT EXISTS "conciliacion_reporte" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clave" varchar(40) NOT NULL, "titulo" varchar(120) NOT NULL, "descripcion" varchar(200) NOT NULL, "nombre_archivo" varchar(150) NOT NULL, "contenido" BLOB NOT NULL, "orden" smallint unsigned NOT NULL CHECK ("orden" >= 0), "conciliacion_id" bigint NOT NULL REFERENCES "conciliacion_conciliacion" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "reporte_unico_por_conciliacion" UNIQUE ("conciliacion_id", "clave"));
CREATE TABLE IF NOT EXISTS "conciliacion_excepcion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "orden" integer unsigned NOT NULL CHECK ("orden" >= 0), "categoria_auto" varchar(20) NOT NULL, "categoria" varchar(20) NOT NULL, "fecha" date NULL, "medio" varchar(40) NOT NULL, "codigo" varchar(40) NOT NULL, "monto" decimal NULL, "monto_registro" decimal NULL, "diferencia" decimal NULL, "detalle" varchar(300) NOT NULL, "sugerencia" text NOT NULL, "estado" varchar(12) NOT NULL, "comentario" text NOT NULL, "actualizada" datetime NULL, "vigente" bool NOT NULL, "actualizada_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "conciliacion_id" bigint NOT NULL REFERENCES "conciliacion_conciliacion" ("id") DEFERRABLE INITIALLY DEFERRED, "reemplazada_por_id" bigint NULL REFERENCES "conciliacion_conciliacion" ("id") DEFERRABLE INITIALLY DEFERRED);

-- -----------------------------------------------------------------------------
-- 2. ÍNDICES
-- -----------------------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX IF NOT EXISTS "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX IF NOT EXISTS "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE UNIQUE INDEX IF NOT EXISTS "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX IF NOT EXISTS "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX IF NOT EXISTS "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX IF NOT EXISTS "auth_user_groups_user_id_group_id_94350c0c_uniq" ON "auth_user_groups" ("user_id", "group_id");
CREATE INDEX IF NOT EXISTS "auth_user_groups_user_id_6a12ed8b" ON "auth_user_groups" ("user_id");
CREATE INDEX IF NOT EXISTS "auth_user_groups_group_id_97559544" ON "auth_user_groups" ("group_id");
CREATE UNIQUE INDEX IF NOT EXISTS "auth_user_user_permissions_user_id_permission_id_14a6b632_uniq" ON "auth_user_user_permissions" ("user_id", "permission_id");
CREATE INDEX IF NOT EXISTS "auth_user_user_permissions_user_id_a95ead1b" ON "auth_user_user_permissions" ("user_id");
CREATE INDEX IF NOT EXISTS "auth_user_user_permissions_permission_id_1fbb5f2c" ON "auth_user_user_permissions" ("permission_id");
CREATE INDEX IF NOT EXISTS "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE INDEX IF NOT EXISTS "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX IF NOT EXISTS "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE INDEX IF NOT EXISTS "conciliacion_configuracion_actualizada_por_id_3dadafa8" ON "conciliacion_configuracion" ("actualizada_por_id");
CREATE INDEX IF NOT EXISTS "conciliacion_conciliacion_usuario_id_84568012" ON "conciliacion_conciliacion" ("usuario_id");
CREATE INDEX IF NOT EXISTS "conciliacion_reporte_clave_efd735f0" ON "conciliacion_reporte" ("clave");
CREATE INDEX IF NOT EXISTS "conciliacion_reporte_conciliacion_id_fe14af1c" ON "conciliacion_reporte" ("conciliacion_id");
CREATE INDEX IF NOT EXISTS "conciliacion_excepcion_actualizada_por_id_ad4915da" ON "conciliacion_excepcion" ("actualizada_por_id");
CREATE INDEX IF NOT EXISTS "conciliacion_excepcion_conciliacion_id_a7aa7ead" ON "conciliacion_excepcion" ("conciliacion_id");
CREATE INDEX IF NOT EXISTS "conciliacion_excepcion_reemplazada_por_id_ca35e357" ON "conciliacion_excepcion" ("reemplazada_por_id");
CREATE INDEX IF NOT EXISTS "conciliacio_vigente_5a9dde_idx" ON "conciliacion_excepcion" ("vigente", "estado", "categoria");

-- -----------------------------------------------------------------------------
-- 3. POBLAMIENTO DE TABLAS (datos ficticios)
-- -----------------------------------------------------------------------------

-- django_migrations: Migraciones aplicadas: le indican a Django que la estructura está al día. (26 filas)

-- django_content_type: Tipos de contenido de Django (uno por modelo). (11 filas)

-- auth_permission: Permisos estándar de Django por modelo. (44 filas)

-- auth_group: Perfiles de usuario: Administrador, Analista de Tesorería y Contador / Auditor. (3 filas)

-- auth_user: Usuarios de prueba, uno por perfil. (3 filas)

-- auth_user_groups: Perfil asignado a cada usuario. (3 filas)

-- conciliacion_bintarjeta: BIN de las tarjetas usadas en los datos de ejemplo. (7 filas)

-- conciliacion_configuracion: Parámetros vigentes de la conciliación (una sola fila). (1 filas)

-- conciliacion_conciliacion: Una conciliación en pesos y una en dólares hechas con los archivos ficticios. (2 filas)

-- conciliacion_reporte: Excel generados por cada conciliación (contenido binario en hexadecimal). (6 filas)

-- conciliacion_excepcion: Excepciones de las dos conciliaciones, con dos ya gestionadas. (9 filas)

-- Contadores de los identificadores autoincrementales
DELETE FROM "sqlite_sequence";

COMMIT;
